import{_ as a,o as s,c as n,a4 as e}from"./chunks/framework.BBs01uty.js";const g=JSON.parse('{"title":"自研 Agent CLI 设计（渐进式学习路线）","description":"","frontmatter":{"title":"自研 Agent CLI 设计（渐进式学习路线）","date":"2026-08-24T00:00:00.000Z"},"headers":[],"relativePath":"ai-agent/self-built-cli.md","filePath":"ai-agent/self-built-cli.md"}'),l={name:"ai-agent/self-built-cli.md"};function i(o,t,d,r,p,h){return s(),n("div",null,[...t[0]||(t[0]=[e(`<h1 id="自研-agent-cli-渐进式学习-ai-agent-内部原理" tabindex="-1">自研 Agent CLI：渐进式学习 AI Agent 内部原理 <a class="header-anchor" href="#自研-agent-cli-渐进式学习-ai-agent-内部原理" aria-label="Permalink to &quot;自研 Agent CLI：渐进式学习 AI Agent 内部原理&quot;">​</a></h1><div class="tip custom-block"><p class="custom-block-title">一句话说清</p><p>从零写一个<strong>接本地 Ollama 的 Agent CLI</strong>（类似 Claude Code 的最小版），按 L1 MVP → L2 可用 → L3 进阶<strong>渐进式推进</strong>。每层一个核心学习目标：先跑通 agent loop，再补可靠性，最后可选探索完整 harness。双目的：①通过自研理解 AI agent 内部原理；②打磨成个人项目亮点。</p></div><h2 id="一、定位与目标" tabindex="-1">一、定位与目标 <a class="header-anchor" href="#一、定位与目标" aria-label="Permalink to &quot;一、定位与目标&quot;">​</a></h2><h3 id="两个目的" tabindex="-1">两个目的 <a class="header-anchor" href="#两个目的" aria-label="Permalink to &quot;两个目的&quot;">​</a></h3><table tabindex="0"><thead><tr><th>目的</th><th>含义</th><th>决定的设计取向</th></tr></thead><tbody><tr><td><strong>学习</strong></td><td>理解 agent loop、工具协议、权限、上下文管理的真实原理</td><td>每层设置明确的&quot;学习要点&quot;，只做该层该学的事</td></tr><tr><td><strong>亮点</strong></td><td>做得好可成为个人项目展示</td><td>架构清晰、README/demo 可展示、有对比视角（vs Claude Code/dsh）</td></tr></tbody></table><h3 id="定位-学习工具-不是替代品" tabindex="-1">定位：学习工具，不是替代品 <a class="header-anchor" href="#定位-学习工具-不是替代品" aria-label="Permalink to &quot;定位：学习工具，不是替代品&quot;">​</a></h3><p>不重复造轮子——Claude Code、dsh 已经是产品级。这个 CLI 的价值在<strong>过程</strong>：亲手实现一遍后，你会真正理解那些&quot;为什么&quot;（为什么工具 schema 要精确、为什么权限要策略化、为什么 prompt 前缀要稳定）。</p><h3 id="硬约束" tabindex="-1">硬约束 <a class="header-anchor" href="#硬约束" aria-label="Permalink to &quot;硬约束&quot;">​</a></h3><ul><li><strong>接本地 Ollama</strong>（已验证 qwen3:8b 支持 tools，OpenAI 兼容接口）</li><li><strong>渐进式</strong>：每层可独立验收，不推倒重来</li><li><strong>简洁</strong>：只做当前层的事，避免提前引入 L3 复杂度</li></ul><h2 id="二、已有基础-不是从零" tabindex="-1">二、已有基础（不是从零） <a class="header-anchor" href="#二、已有基础-不是从零" aria-label="Permalink to &quot;二、已有基础（不是从零）&quot;">​</a></h2><table tabindex="0"><thead><tr><th>资产</th><th>状态</th><th>对 CLI 的价值</th></tr></thead><tbody><tr><td><code>verify-tool-calling.ts</code></td><td>✅ 已验证 agent loop + tools 链路</td><td>L1 的 loop 骨架直接复用思路</td></tr><tr><td>Ollama qwen3:8b</td><td>✅ 在线，支持 tools</td><td>LLM 后端就绪</td></tr><tr><td>dev-agent-harness</td><td>成熟</td><td>skills/workflow 概念可借鉴，但 CLI 保持独立</td></tr><tr><td>Claude Code 架构笔记</td><td>已研究</td><td>作为 L2/L3 的&quot;参考答案&quot;</td></tr></tbody></table><h2 id="三、总体架构" tabindex="-1">三、总体架构 <a class="header-anchor" href="#三、总体架构" aria-label="Permalink to &quot;三、总体架构&quot;">​</a></h2><div class="language-mermaid vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">mermaid</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">graph TD</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    subgraph L1[MVP 层]</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">        A[REPL 输入] --&gt; B[Agent Loop]</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">        B --&gt; C[LLM 调用 Ollama]</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">        B --&gt; D[工具执行]</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">        D --&gt; B</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    end</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    subgraph L2[可靠性层]</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">        E[权限确认]</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">        F[会话持久化]</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">        G[上下文管理]</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">        H[错误恢复]</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    end</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    subgraph L3[进阶层 - 可选]</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">        I[Hooks]</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">        J[子代理]</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">        K[MCP 集成]</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    end</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    L1 --&gt; L2</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    L2 --&gt; L3</span></span></code></pre></div><p>核心是 <strong>agent loop</strong>（已由验证脚本证明可行）：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>while (true) {</span></span>
<span class="line"><span>  收集 LLM 流式输出（content + tool_calls）</span></span>
<span class="line"><span>  if (无 tool_calls) break        // 模型准备好回答</span></span>
<span class="line"><span>  执行工具 → 结果回传 messages    // 继续下一轮</span></span>
<span class="line"><span>}</span></span></code></pre></div><h2 id="四、渐进式路线" tabindex="-1">四、渐进式路线 <a class="header-anchor" href="#四、渐进式路线" aria-label="Permalink to &quot;四、渐进式路线&quot;">​</a></h2><h3 id="l1-mvp-跑通-agent-loop-核心学习目标-loop-与工具协议" tabindex="-1">L1 MVP：跑通 agent loop（核心学习目标：<strong>loop 与工具协议</strong>） <a class="header-anchor" href="#l1-mvp-跑通-agent-loop-核心学习目标-loop-与工具协议" aria-label="Permalink to &quot;L1 MVP：跑通 agent loop（核心学习目标：**loop 与工具协议**）&quot;">​</a></h3><p><strong>功能</strong>：</p><ul><li>REPL 交互（readline 一行输入）</li><li>3 个工具：<code>Bash</code>、<code>Read</code>、<code>Write</code></li><li>agent loop 多轮循环 + 流式输出</li><li>简单 system prompt（你是通用编程助手）</li></ul><p><strong>技术点</strong>：</p><ul><li>流式 <code>tool_calls</code> 累积（delta 分段拼接）</li><li>参数 JSON 解析 + 容错（解析失败回传给模型重试）</li><li>循环上限（3 轮）+ 错误路径（工具失败也回传结果）</li></ul><p><strong>验收标准</strong>：能完成&quot;帮我建一个 hello.js 并运行&quot;这类多工具任务（Write → Bash 运行 → 读输出 → 回答）。</p><p><strong>学习要点</strong>：</p><ol><li>tool_use 是&quot;控制信号&quot;不是&quot;函数调用&quot;——它决定 loop 是否继续</li><li>工具结果必须标准化回传（<code>role: &#39;tool&#39;</code> + tool_call_id 配对），模型才能继续</li><li>参数不可信：LLM 生成的 JSON 需要解析容错和校验</li></ol><h3 id="l2-可用-可靠性-核心学习目标-权限与上下文管理" tabindex="-1">L2 可用：可靠性（核心学习目标：<strong>权限与上下文管理</strong>） <a class="header-anchor" href="#l2-可用-可靠性-核心学习目标-权限与上下文管理" aria-label="Permalink to &quot;L2 可用：可靠性（核心学习目标：**权限与上下文管理**）&quot;">​</a></h3><p><strong>功能</strong>：</p><ul><li>权限确认：危险命令（rm、git push）交互确认，allow/deny 规则，<code>--dangerously-skip-permissions</code> 模式</li><li>工具参数校验：用 zod 对工具输入做 schema 校验</li><li>会话持久化：JSONL transcript + <code>--resume</code></li><li>上下文管理：消息窗口上限 + 简单压缩（超限时摘要历史）</li><li>错误恢复：API 断流重试、工具失败回传、循环上限</li></ul><p><strong>验收标准</strong>：长对话（20+ 轮）不崩溃、上下文压缩后仍能回答问题、危险操作会被拦截确认。</p><p><strong>学习要点</strong>：</p><ol><li><strong>权限是策略引擎不是弹窗</strong>：决策流水线（deny → ask → allow）顺序本身就是安全模型；bypass 不能绕过 deny</li><li><strong>上下文是&quot;字节稳定性&quot;问题</strong>：压缩、摘要、会话边界怎么做才不会丢关键信息（对照 Claude Code 的 cache-safe forking）</li><li><strong>状态机思维</strong>：会话状态（消息、任务、恢复点）显式建模，而非递归</li></ol><h3 id="l3-进阶-可选-按需-完整-harness" tabindex="-1">L3 进阶（可选，按需）：完整 harness <a class="header-anchor" href="#l3-进阶-可选-按需-完整-harness" aria-label="Permalink to &quot;L3 进阶（可选，按需）：完整 harness&quot;">​</a></h3><p><strong>功能</strong>：Hooks（PreToolUse/PostToolUse）、子代理（独立上下文）、MCP 集成、插件化。</p><p><strong>学习要点</strong>：这些是 Claude Code 的深度——做到这层说明你已经掌握 agent 的完整图景。<strong>建议 L2 稳定跑一段时间后再决定</strong>，避免范围蔓延。</p><h2 id="五、技术选型" tabindex="-1">五、技术选型 <a class="header-anchor" href="#五、技术选型" aria-label="Permalink to &quot;五、技术选型&quot;">​</a></h2><table tabindex="0"><thead><tr><th>项</th><th>选择</th><th>理由</th></tr></thead><tbody><tr><td>语言</td><td>Node.js + TypeScript</td><td>已熟悉，type 安全适合工具 schema</td></tr><tr><td>LLM 调用</td><td><code>openai</code> SDK（baseURL 指 Ollama）或直接 fetch</td><td>SDK 已兼容，验证过</td></tr><tr><td>LLM 后端</td><td>Ollama qwen3:8b（可换）</td><td>本地免费，支持 tools</td></tr><tr><td>参数校验</td><td>zod</td><td>schema 即文档，校验即安全</td></tr><tr><td>终端交互</td><td>readline → 后续可换 ink/react 渲染</td><td>MVP 不引入渲染复杂度</td></tr><tr><td>存储</td><td>JSONL 文件</td><td>可读、可恢复、无数据库依赖</td></tr></tbody></table><h2 id="六、每层学到的原理汇总" tabindex="-1">六、每层学到的原理汇总 <a class="header-anchor" href="#六、每层学到的原理汇总" aria-label="Permalink to &quot;六、每层学到的原理汇总&quot;">​</a></h2><table tabindex="0"><thead><tr><th>层</th><th>组件</th><th>学到的原理</th><th>对应真实系统</th></tr></thead><tbody><tr><td>L1</td><td>agent loop</td><td>工具调用是控制信号、结果标准化回传、参数容错</td><td>Claude Code <code>query.ts</code></td></tr><tr><td>L1</td><td>流式 tool_calls</td><td>delta 累积、分段拼接</td><td>各 LLM API</td></tr><tr><td>L2</td><td>权限引擎</td><td>决策流水线、bypass 边界、allow/deny 规则</td><td>Claude Code <code>permissions.ts</code></td></tr><tr><td>L2</td><td>上下文管理</td><td>压缩策略、会话边界、字节稳定性</td><td>Claude Code compaction</td></tr><tr><td>L2</td><td>会话持久化</td><td>状态机、断点恢复</td><td><code>~/.claude/projects/</code> JSONL</td></tr><tr><td>L3</td><td>hooks/子代理</td><td>事件驱动、上下文隔离</td><td>Claude Code hooks/AgentTool</td></tr></tbody></table><h2 id="七、项目亮点打磨" tabindex="-1">七、项目亮点打磨 <a class="header-anchor" href="#七、项目亮点打磨" aria-label="Permalink to &quot;七、项目亮点打磨&quot;">​</a></h2><p>（用户明确希望可作亮点——放在<strong>好用之后</strong>，不喧宾夺主）</p><ul><li><strong>README</strong>：一张架构图 + 一次 demo 录屏（多工具调用过程）+ 对比视角（vs Claude Code 最小版）</li><li><strong>验证沉淀</strong>：像本知识库一样，每层写一篇&quot;实现笔记&quot;，把踩坑和原理沉淀成文（既是学习也是展示）</li><li><strong>增量演示</strong>：L1 就能演示&quot;让 CLI 自己写代码并运行&quot;，L2 演示&quot;长对话不丢上下文&quot;</li><li><strong>技术债克制</strong>：每层代码量小、命名清晰，本身就是最好的展示</li></ul><h2 id="八、风险" tabindex="-1">八、风险 <a class="header-anchor" href="#八、风险" aria-label="Permalink to &quot;八、风险&quot;">​</a></h2><table tabindex="0"><thead><tr><th>风险</th><th>说明</th><th>缓解</th></tr></thead><tbody><tr><td><strong>重复造轮子</strong></td><td>dsh/Claude Code 已存在</td><td>定位&quot;学习+定制&quot;；README 明示是教育项目，不宣称替代</td></tr><tr><td><strong>范围蔓延</strong></td><td>想一口气做 hooks/子代理</td><td>严格按层推进，L3 按需，先让 L1/L2 稳定</td></tr><tr><td><strong>本地模型能力边界</strong></td><td>qwen3:8b 复杂决策弱、延迟高</td><td>工具 description 写清触发条件；L1 用简单任务验证</td></tr><tr><td><strong>安全事故</strong></td><td>危险命令执行</td><td>L1 就带最小确认；rm/rm -rf 一律拦截</td></tr><tr><td><strong>学习目标稀释</strong></td><td>写着写着变成&quot;把代码写完&quot;</td><td>每层先写&quot;学习要点&quot;，先懂原理再动手</td></tr></tbody></table><h2 id="九、路线图" tabindex="-1">九、路线图 <a class="header-anchor" href="#九、路线图" aria-label="Permalink to &quot;九、路线图&quot;">​</a></h2><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Phase 1（本周）：L1 MVP</span></span>
<span class="line"><span>  - 骨架：REPL + agent loop + 3 工具 + 流式</span></span>
<span class="line"><span>  - 验收：多工具协作任务跑通</span></span>
<span class="line"><span>  - 产出：实现笔记《agent loop 是怎么转起来的》</span></span>
<span class="line"><span></span></span>
<span class="line"><span>Phase 2（渐进）：L2 可用</span></span>
<span class="line"><span>  - 权限确认 → 会话持久化 → 上下文管理 → 错误恢复</span></span>
<span class="line"><span>  - 验收：20+ 轮长对话稳定</span></span>
<span class="line"><span>  - 产出：实现笔记《权限引擎》《上下文压缩》</span></span>
<span class="line"><span></span></span>
<span class="line"><span>Phase 3（按需）：L3 进阶</span></span>
<span class="line"><span>  - hooks → 子代理 → MCP</span></span>
<span class="line"><span>  - 评估后再启动</span></span></code></pre></div><h2 id="十、下一步" tabindex="-1">十、下一步 <a class="header-anchor" href="#十、下一步" aria-label="Permalink to &quot;十、下一步&quot;">​</a></h2><ol><li>确定项目名与目录（建议 <code>code/agent-cli</code>）</li><li>Phase 1 起步：搭骨架（agent loop + REPL + Bash/Read/Write 三工具）</li><li>每层完成后更新本设计文档的状态标记</li></ol><h2 id="延伸阅读" tabindex="-1">延伸阅读 <a class="header-anchor" href="#延伸阅读" aria-label="Permalink to &quot;延伸阅读&quot;">​</a></h2><ul><li><a href="/knowledge/ai-agent/function-calling.html">Function Calling 与工具调用</a> - 工具机制基础</li><li><a href="/knowledge/ai-agent/app-architecture.html">AI 应用架构模式</a> - Agent 循环与架构</li><li><a href="/knowledge/ai-agent/case-studies/claude-code-memory.html">Claude Code 记忆机制</a> - 参考实现</li><li><a href="/knowledge/ai-agent/case-studies/deepseek-harness.html">DeepSeek Harness 案例研究</a> - 现成开源 harness</li></ul>`,48)])])}const u=a(l,[["render",i]]);export{g as __pageData,u as default};
